mkuse!{use super :: sealed :: Sealed ;}
mkuse!{use crate :: simd :: { LaneCount , Mask , Simd , SupportedLaneCount , cmp :: SimdPartialEq , num :: SimdUint } ;}
mkitem!{mktrait!{# [doc = " Operations on SIMD vectors of constant pointers."] pub trait SimdConstPtr : Copy + Sealed { # [doc = " Vector of `usize` with the same number of elements."] type Usize ; # [doc = " Vector of `isize` with the same number of elements."] type Isize ; # [doc = " Vector of const pointers with the same number of elements."] type CastPtr < T > ; # [doc = " Vector of mutable pointers to the same type."] type MutPtr ; # [doc = " Mask type used for manipulating this SIMD vector type."] type Mask ; # [doc = " Returns `true` for each element that is null."] fn is_null (self) -> Self :: Mask ; # [doc = " Casts to a pointer of another type."] # [doc = ""] # [doc = " Equivalent to calling [`pointer::cast`] on each element."] fn cast < T > (self) -> Self :: CastPtr < T > ; # [doc = " Changes constness without changing the type."] # [doc = ""] # [doc = " Equivalent to calling [`pointer::cast_mut`] on each element."] fn cast_mut (self) -> Self :: MutPtr ; # [doc = " Gets the \"address\" portion of the pointer."] # [doc = ""] # [doc = " This method discards pointer semantic metadata, so the result cannot be"] # [doc = " directly cast into a valid pointer."] # [doc = ""] # [doc = " This method semantically discards *provenance* and"] # [doc = " *address-space* information. To properly restore that information, use [`Self::with_addr`]."] # [doc = ""] # [doc = " Equivalent to calling [`pointer::addr`] on each element."] fn addr (self) -> Self :: Usize ; # [doc = " Converts an address to a pointer without giving it any provenance."] # [doc = ""] # [doc = " Without provenance, this pointer is not associated with any actual allocation. Such a"] # [doc = " no-provenance pointer may be used for zero-sized memory accesses (if suitably aligned), but"] # [doc = " non-zero-sized memory accesses with a no-provenance pointer are UB. No-provenance pointers"] # [doc = " are little more than a usize address in disguise."] # [doc = ""] # [doc = " This is different from [`Self::with_exposed_provenance`], which creates a pointer that picks up a"] # [doc = " previously exposed provenance."] # [doc = ""] # [doc = " Equivalent to calling [`core::ptr::without_provenance`] on each element."] fn without_provenance (addr : Self :: Usize) -> Self ; # [doc = " Creates a new pointer with the given address."] # [doc = ""] # [doc = " This performs the same operation as a cast, but copies the *address-space* and"] # [doc = " *provenance* of `self` to the new pointer."] # [doc = ""] # [doc = " Equivalent to calling [`pointer::with_addr`] on each element."] fn with_addr (self , addr : Self :: Usize) -> Self ; # [doc = " Exposes the \"provenance\" part of the pointer for future use in"] # [doc = " [`Self::with_exposed_provenance`] and returns the \"address\" portion."] fn expose_provenance (self) -> Self :: Usize ; # [doc = " Converts an address back to a pointer, picking up a previously \"exposed\" provenance."] # [doc = ""] # [doc = " Equivalent to calling [`core::ptr::with_exposed_provenance`] on each element."] fn with_exposed_provenance (addr : Self :: Usize) -> Self ; # [doc = " Calculates the offset from a pointer using wrapping arithmetic."] # [doc = ""] # [doc = " Equivalent to calling [`pointer::wrapping_offset`] on each element."] fn wrapping_offset (self , offset : Self :: Isize) -> Self ; # [doc = " Calculates the offset from a pointer using wrapping arithmetic."] # [doc = ""] # [doc = " Equivalent to calling [`pointer::wrapping_add`] on each element."] fn wrapping_add (self , count : Self :: Usize) -> Self ; # [doc = " Calculates the offset from a pointer using wrapping arithmetic."] # [doc = ""] # [doc = " Equivalent to calling [`pointer::wrapping_sub`] on each element."] fn wrapping_sub (self , count : Self :: Usize) -> Self ; }}}
mkitem!{mkimpl!{impl < T , const N : usize > Sealed for Simd < * const T , N > where LaneCount < N > : SupportedLaneCount { }}}
mkitem!{mkimpl!{impl < T , const N : usize > SimdConstPtr for Simd < * const T , N > where LaneCount < N > : SupportedLaneCount , { type Usize = Simd < usize , N > ; type Isize = Simd < isize , N > ; type CastPtr < U > = Simd < * const U , N > ; type MutPtr = Simd < * mut T , N > ; type Mask = Mask < isize , N > ; # [inline] fn is_null (self) -> Self :: Mask { Simd :: splat (core :: ptr :: null ()) . simd_eq (self) } # [inline] fn cast < U > (self) -> Self :: CastPtr < U > { use core :: ptr :: Pointee ; assert_eq ! (size_of ::<< T as Pointee >:: Metadata > () , 0) ; assert_eq ! (size_of ::<< U as Pointee >:: Metadata > () , 0) ; unsafe { core :: intrinsics :: simd :: simd_cast_ptr (self) } } # [inline] fn cast_mut (self) -> Self :: MutPtr { unsafe { core :: intrinsics :: simd :: simd_cast_ptr (self) } } # [inline] fn addr (self) -> Self :: Usize { unsafe { core :: mem :: transmute_copy (& self) } } # [inline] fn without_provenance (addr : Self :: Usize) -> Self { unsafe { core :: mem :: transmute_copy (& addr) } } # [inline] fn with_addr (self , addr : Self :: Usize) -> Self { self . cast :: < u8 > () . wrapping_offset (addr . cast :: < isize > () - self . addr () . cast :: < isize > ()) . cast () } # [inline] fn expose_provenance (self) -> Self :: Usize { unsafe { core :: intrinsics :: simd :: simd_expose_provenance (self) } } # [inline] fn with_exposed_provenance (addr : Self :: Usize) -> Self { unsafe { core :: intrinsics :: simd :: simd_with_exposed_provenance (addr) } } # [inline] fn wrapping_offset (self , count : Self :: Isize) -> Self { unsafe { core :: intrinsics :: simd :: simd_arith_offset (self , count) } } # [inline] fn wrapping_add (self , count : Self :: Usize) -> Self { self . wrapping_offset (count . cast ()) } # [inline] fn wrapping_sub (self , count : Self :: Usize) -> Self { self . wrapping_offset (- count . cast :: < isize > ()) } }}}